export function ownersOf(details){const m=details&&details.manifest||{};const a=m.adapter&&m.adapter.name?m.adapter:null;return{policy:!m.model?null:details.policy_deleted?{gone:true,named:true}:{route:m.model},benchmark:!m.benchmark?null:m.benchmark_deleted?{gone:true}:{route:m.benchmark},adapter:!a?null:a.deleted?{gone:true}:{route:a.name}}}export function deletedPolicy(name,at){const t=Date.parse(at||"");return`${name} (deleted${Number.isFinite(t)?` ${new Date(t).toISOString().slice(5,10)} UTC`:""})`}export function ownerPart(text,owner,href){if(!owner)return{text:text};if(owner.gone)return{text:owner.named?text:`${text} (deleted)`};return{text:text,href:href(owner.route)}}